import { NodeMaterial, MeshStandardNodeMaterial, MeshBasicNodeMaterial, Group, Mesh, PlaneGeometry, Color, DoubleSide } from 'three/webgpu';
import { uv, uniform, float, vec3, vec4, mix, smoothstep, positionLocal, time } from 'three/tsl';

export default function createNode(config, ctx) {
  const root = new Group();
  root.name = 'data-ticker-ribbon';
  const [px, py, pz] = config.scenePosition?.position ?? [0, 0, 0];
  const [rx, ry, rz] = config.scenePosition?.rotation ?? [0, 0, 0];
  const [sx, sy, sz] = config.scenePosition?.scale ?? [1, 1, 1];
  root.position.set(px, py, pz);
  root.rotation.set(rx, ry, rz);
  root.scale.set(sx, sy, sz);

  const RIBBON_W = 7.0;
  const RIBBON_H = 0.35;

  const disposables = [];

  // rail plane
  const railGeo = new PlaneGeometry(RIBBON_W, RIBBON_H);
  const railMat = new MeshStandardNodeMaterial({
    color: new Color('#111117'),
    roughness: 0.6,
    metalness: 0.2,
    side: DoubleSide,
  });
  const rail = new Mesh(railGeo, railMat);
  rail.position.z = 0;
  root.add(rail);
  disposables.push(railGeo, railMat);

  // hairlines top/bottom
  const hairH = 0.006;
  const hairGeo = new PlaneGeometry(RIBBON_W, hairH);
  const hairMat = new MeshStandardNodeMaterial({
    color: new Color('#23232b'),
    roughness: 0.5,
    metalness: 0.2,
    side: DoubleSide,
  });
  const hairTop = new Mesh(hairGeo, hairMat);
  hairTop.position.set(0, RIBBON_H / 2 - hairH / 2, 0.001);
  const hairBottom = new Mesh(hairGeo, hairMat);
  hairBottom.position.set(0, -RIBBON_H / 2 + hairH / 2, 0.001);
  root.add(hairTop, hairBottom);
  disposables.push(hairGeo, hairMat);

  // content strip
  const entries = (config.textContent ?? []).map(t => (typeof t === 'string' ? t : t.text));
  const strings = entries.length
    ? entries
    : ['CAL NA-01 BEAT 28800 VPH', 'POWER RESERVE 72H', 'CASE 40.5 MM 904L', 'REF 5811 IN STOCK', 'WAITLIST 1204', 'NEXT FITTING JUL 18'];

  const tickW = 0.02;
  const tickH = 0.14;
  const gap = 0.5;

  const contentGroup = new Group();
  const textMeshes = [];
  const tickMeshes = [];
  const tickGeo = new PlaneGeometry(tickW, tickH);
  const tickMat = new MeshStandardNodeMaterial({
    color: new Color('#ff2a38'),
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 1.5,
    roughness: 0.5,
    metalness: 0.2,
  });
  disposables.push(tickGeo, tickMat);

  function buildStrip(offsetX) {
    let cursorX = offsetX;
    strings.forEach((str, i) => {
      const textMesh = ctx.fontAtlas.createText(str, {
        family: 'JetBrains Mono',
        fontSize: 13,
        fontWeight: 700,
        letterSpacing: 0.06,
        lineHeight: 1,
        color: '#e8ecf2',
      });
      textMesh.position.set(cursorX, 0, 0.02);
      contentGroup.add(textMesh);
      textMeshes.push(textMesh);

      const bbox = ctx.fontAtlas.measure
        ? ctx.fontAtlas.measure(str, { fontSize: 13, letterSpacing: 0.06 })
        : { width: str.length * 0.09 };
      cursorX += bbox.width + gap;

      const tick = new Mesh(tickGeo, tickMat);
      tick.position.set(cursorX, 0, 0.02);
      contentGroup.add(tick);
      tickMeshes.push(tick);
      cursorX += gap;
    });
    return cursorX - offsetX;
  }

  const stripLen = buildStrip(0);
  buildStrip(stripLen);

  root.add(contentGroup);

  // edge fade overlay planes
  const fadeW = 0.6;
  const stops = config.visualSpec?.colors?.gradientStops ?? [
    { at: 0, hex: '#0b0b10ff' },
    { at: 0.09, hex: '#0b0b1000' },
    { at: 0.91, hex: '#0b0b1000' },
    { at: 1, hex: '#0b0b10ff' },
  ];

  function hexToColorAlpha(hex) {
    const h = hex.replace('#', '');
    const r = parseInt(h.substring(0, 2), 16) / 255;
    const g = parseInt(h.substring(2, 4), 16) / 255;
    const b = parseInt(h.substring(4, 6), 16) / 255;
    const a = h.length >= 8 ? parseInt(h.substring(6, 8), 16) / 255 : 1;
    return { color: new Color(r, g, b), alpha: a };
  }

  const leftStops = stops.slice(0, 2);
  const rightStops = stops.slice(2, 4);

  function makeFadeMaterial(sideStops) {
    const c0 = hexToColorAlpha(sideStops[0].hex);
    const c1 = hexToColorAlpha(sideStops[1].hex);
    const uvNode = uv();
    const t = smoothstep(float(sideStops[0].at), float(sideStops[1].at), uvNode.x);
    const colorNode = mix(vec3(c0.color.r, c0.color.g, c0.color.b), vec3(c1.color.r, c1.color.g, c1.color.b), t);
    const alphaNode = mix(float(c0.alpha), float(c1.alpha), t);
    const mat = new MeshBasicNodeMaterial({ transparent: true });
    mat.colorNode = colorNode;
    mat.opacityNode = alphaNode;
    return mat;
  }

  const fadeGeo = new PlaneGeometry(fadeW, RIBBON_H + 0.01);
  const leftFadeMat = makeFadeMaterial(leftStops);
  const rightFadeMat = makeFadeMaterial(rightStops);
  const leftFade = new Mesh(fadeGeo, leftFadeMat);
  leftFade.position.set(-RIBBON_W / 2 + fadeW / 2, 0, 0.03);
  const rightFade = new Mesh(fadeGeo, rightFadeMat);
  rightFade.position.set(RIBBON_W / 2 - fadeW / 2, 0, 0.03);
  root.add(leftFade, rightFade);
  disposables.push(fadeGeo, leftFadeMat, rightFadeMat);

  // apply fly-through primitive for constant leftward velocity with seamless loop
  const flyParams = { depthUnits: 0, speed: 0.4, loopLength: stripLen, direction: 'left' };
  ctx.primitives['fly-through'](contentGroup, flyParams);

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    disposables.forEach(d => d.dispose && d.dispose());
    textMeshes.forEach(m => {
      if (m.geometry) m.geometry.dispose();
      if (m.material) m.material.dispose();
    });
    tickMeshes.forEach(m => {});
    if (gsapGlobalCheck()) {}
  };

  function gsapGlobalCheck() {
    return false;
  }

  return root;
}
